'use strict';

const initialLoadState = Object.freeze({
  selected: null,
  isLoading: false,
  isSuccess: false,
  isError: false,
  message: ''
});

function plain(value) {
  if (value === null || typeof value !== 'object') return false;
  const proto = Object.getPrototypeOf(value);
  return proto === Object.prototype || proto === null;
}

function exactKeys(value, keys) {
  const actual = Object.keys(value).sort();
  const expected = keys.slice().sort();
  return actual.length === expected.length && actual.every((key, i) => key === expected[i]);
}

function reduceItemLoad(state, event) {
  const stateKeys = ['selected', 'isLoading', 'isSuccess', 'isError', 'message'];
  if (!plain(state) || !exactKeys(state, stateKeys)) throw new TypeError('invalid state');
  if (state.selected !== null && !plain(state.selected)) throw new TypeError('invalid selected');
  if (typeof state.isLoading !== 'boolean' || typeof state.isSuccess !== 'boolean' ||
      typeof state.isError !== 'boolean' || typeof state.message !== 'string') {
    throw new TypeError('invalid state values');
  }
  if (!plain(event) || typeof event.type !== 'string') throw new TypeError('invalid event');

  if (event.type === 'START') {
    if (!exactKeys(event, ['type'])) throw new TypeError('invalid START');
    return { selected: null, isLoading: true, isSuccess: false, isError: false, message: '' };
  }
  if (event.type === 'SUCCEED') {
    if (!exactKeys(event, ['type', 'item']) || !plain(event.item)) throw new TypeError('invalid SUCCEED');
    return { selected: { ...event.item }, isLoading: false, isSuccess: true, isError: false, message: '' };
  }
  if (event.type === 'FAIL') {
    if (!exactKeys(event, ['type', 'message']) || typeof event.message !== 'string') throw new TypeError('invalid FAIL');
    return { selected: null, isLoading: true, isSuccess: false, isError: true, message: event.message };
  }
  if (event.type === 'RESET') {
    if (!exactKeys(event, ['type'])) throw new TypeError('invalid RESET');
    return { ...initialLoadState };
  }
  throw new TypeError('unknown event');
}

module.exports = { initialLoadState, reduceItemLoad };

