'use strict';
const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api).sort(), ['initialLoadState', 'reduceItemLoad']);
const { initialLoadState, reduceItemLoad } = api;
const typeError = fn => assert.throws(fn, TypeError);
const initial = { selected: null, isLoading: false, isSuccess: false, isError: false, message: '' };
assert.deepStrictEqual(initialLoadState, initial);
assert.strictEqual(Object.isFrozen(initialLoadState), true);

const startInput = { selected: { id: 1 }, isLoading: false, isSuccess: true, isError: false, message: 'old' };
const started = reduceItemLoad(startInput, { type: 'START' });
assert.deepStrictEqual(started, { selected: null, isLoading: true, isSuccess: false, isError: false, message: '' });
assert.notStrictEqual(started, startInput);
assert.deepStrictEqual(startInput, { selected: { id: 1 }, isLoading: false, isSuccess: true, isError: false, message: 'old' });

const item = { id: 7, name: 'item' };
const event = { type: 'SUCCEED', item };
const succeeded = reduceItemLoad(started, event);
assert.deepStrictEqual(succeeded, { selected: { id: 7, name: 'item' }, isLoading: false, isSuccess: true, isError: false, message: '' });
assert.notStrictEqual(succeeded.selected, item);
item.name = 'changed';
assert.strictEqual(succeeded.selected.name, 'item');
const failed = reduceItemLoad(succeeded, { type: 'FAIL', message: '' });
assert.deepStrictEqual(failed, { selected: null, isLoading: false, isSuccess: false, isError: true, message: '' });
const reset = reduceItemLoad(failed, { type: 'RESET' });
assert.deepStrictEqual(reset, initial);
assert.notStrictEqual(reset, initialLoadState);
assert.notStrictEqual(reduceItemLoad(reset, { type: 'RESET' }), reset);

typeError(() => reduceItemLoad(null, { type: 'RESET' }));
typeError(() => reduceItemLoad({ ...initial, extra: 1 }, { type: 'RESET' }));
typeError(() => reduceItemLoad({ ...initial, isLoading: 0 }, { type: 'RESET' }));
typeError(() => reduceItemLoad(initial, null));
typeError(() => reduceItemLoad(initial, { type: 'START', extra: 1 }));
typeError(() => reduceItemLoad(initial, { type: 'SUCCEED' }));
typeError(() => reduceItemLoad(initial, { type: 'SUCCEED', item: [] }));
typeError(() => reduceItemLoad(initial, { type: 'FAIL', message: 1 }));
typeError(() => reduceItemLoad(initial, { type: 'RESET', item: {} }));
typeError(() => reduceItemLoad(initial, { type: 'UNKNOWN' }));

